  ('ingrate', '/ˈɪn.ɡreɪt/', '忘恩负义的人', 'A person who shows no gratitude or appreciation.'),
  ('remonstrance', '/rɪˈmɒn.strəns/', '抗议；反对', 'A protest or objection against something, typically in writing.'),
  ('testy', '/ˈtɛs.ti/', '易怒的', 'Easily irritated or annoyed; quick to anger.'),
  ('stinginess', '/ˈstɪn.dʒɪ.nəs/', '吝啬', 'Excessive unwillingness to spend money or use resources.'),
  ('agronomy', '/əˈɡrɒn.ə.mi/', '农业科学', 'The science of soil management and crop production.'),
  ('intercessor', '/ˌɪntərˈsɛsər/', '代祷者', 'A person who intervenes on behalf of another, often in prayer.'),
