  ('sod', '/sɑd/', '草皮；土壤', 'A piece of earth or turf covered with grass.'),
  ('labile', '/ˈleɪ.baɪl/', '不稳定的', 'Easily altered or changed; unstable or variable.'),
  ('palaver', '/pəˈlæ.vər/', '闲聊；无谓的争论', 'Unproductive discussion or debate, often lengthy and irrelevant.'),
  ('persnickety', '/pərˈsnɪk.ɪ.ti/', '挑剔的；过于讲究的', 'Excessively particular or demanding; fussy about details.'),
  ('diehard', '/ˈdaɪ.hɑrd/', '顽固支持者', 'A person with stubborn loyalty or devotion to a cause or belief.'),
  ('seemly', '/ˈsiːm.li/', '得体的', 'Proper, decent, or fitting in behavior or appearance.'),
  ('modish', '/ˈmoʊ.dɪʃ/', '时髦的；流行的', 'In fashion; stylish and contemporary in appearance.'),
  ('adumbrate', '/ˈæd.ʌm.breɪt/', '预示；勾勒出', 'To indicate or suggest something in an incomplete way.'),
  ('preponderant', '/prɪˈpɒndərənt/', '占优势的', 'Having greater importance or influence than others.'),
  ('execrable', '/ˈɛk.sɪ.krə.bəl/', '可恶的；糟糕的', 'Extremely bad or unpleasant; deserving of hate.'),
  ('tautological', '/ˌtɔː.təˈlɑː.dʒɪ.kəl/', '同义反复的', 'Involving unnecessary repetition of meaning or expression.'),
  ('delectation', '/ˌdɛlɛkˈteɪʃən/', '乐趣；享受', 'Pleasurable enjoyment or delight in something.'),
  ('depressant', '/dɪˈprɛs.ənt/', '抑制剂', 'A substance that reduces physiological or psychological activity.'),
  ('ossify', '/ˈɑː.sɪ.faɪ/', '硬化', 'To become or cause to become rigid and inflexible.'),
  ('recondite', '/ˈrɛ.kən.daɪt/', '深奥的；难解的', 'Difficult to understand; obscure or requiring specialized knowledge.'),
  ('crepuscular', '/krɪˈpʌs.kjə.lɚ/', '黄昏时的；黎明前的', 'Relating to twilight or the time just before nightfall.'),
  ('perfidious', '/pərˈfɪd.i.əs/', '背叛的；不忠的', 'Disloyal and deceitful in a trust or relationship.'),
  ('coterminous', '/koʊˈtɜːr.mɪ.nəs/', '接壤的；相邻的', 'Having a common boundary or border; adjacent.'),
