  ('puerile', '/ˈpjʊə.raɪl/', '幼稚的；天真的', 'Childishly silly or trivial; lacking maturity.'),
  ('ambidextrous', '/ˌæm.bɪˈdɛk.strəs/', '双手灵巧的', 'Able to use both hands equally well.'),
  ('prehensile', '/prɪˈhɛn.saɪl/', '可抓握的；适于抓取的', 'Adapted for grasping, especially by a limb or tail.'),
